import 'dart:typed_data';
import 'dart:ui';

/// Court figures from `assets/court/{jack,queen,king}.svg`.
/// Each SVG already includes both mirrored halves — paint once as fills.
List<Path> jackSvgFills() => _jackFills;
List<Path> queenSvgFills() => _queenFills;
List<Path> kingSvgFills() => _kingFills;

final List<Path> _jackFills = _buildFills(0.05, _jackTop, _jackBottom);
final List<Path> _queenFills = _buildFills(0.05, _queenTop, _queenBottom);
final List<Path> _kingFills = _buildFills(0.1, _kingTop, _kingBottom);

List<Path> _buildFills(double scale, String top, String bottom) {
  final transform = Float64List.fromList([
    scale, 0, 0, 0, //
    0, -scale, 0, 0, //
    0, 0, 1, 0, //
    0, _viewH, 0, 1, //
  ]);
  return [
    _toCardUnit(_parseSvgPath(top), transform),
    _toCardUnit(_parseSvgPath(bottom), transform),
  ];
}

/// ViewBox is landscape 580×386; figures sit in a centred portrait card strip.
const double _viewW = 580;
const double _viewH = 386;
const double _cardAspect = 198 / 287;
const double _cardH = _viewH;
const double _cardW = _cardH * _cardAspect;
const double _cardL = (_viewW - _cardW) / 2;
const double _cardT = 0;

Path _toCardUnit(Path raw, Float64List sourceTransform) {
  final placed = raw.transform(sourceTransform);
  return placed.transform(
    Float64List.fromList([
      1 / _cardW, 0, 0, 0, //
      0, 1 / _cardH, 0, 0, //
      0, 0, 1, 0, //
      -_cardL / _cardW, -_cardT / _cardH, 0, 1, //
    ]),
  );
}

final _token = RegExp(r'[MmLlCcZz]|-?\d*\.?\d+(?:[eE][-+]?\d+)?');

Path _parseSvgPath(String data) {
  final tokens =
      _token.allMatches(data).map((match) => match.group(0)!).toList();
  final path = Path();
  var index = 0;
  var command = '';
  var x = 0.0;
  var y = 0.0;
  var startX = 0.0;
  var startY = 0.0;

  double next() => double.parse(tokens[index++]);

  while (index < tokens.length) {
    final token = tokens[index];
    if (RegExp(r'^[A-Za-z]$').hasMatch(token)) {
      command = token;
      index++;
      if (command == 'Z' || command == 'z') {
        path.close();
        x = startX;
        y = startY;
        command = '';
        continue;
      }
    }
    switch (command) {
      case 'M':
      case 'm':
        final relative = command == 'm';
        x = relative ? x + next() : next();
        y = relative ? y + next() : next();
        path.moveTo(x, y);
        startX = x;
        startY = y;
        command = relative ? 'l' : 'L';
      case 'L':
      case 'l':
        final relative = command == 'l';
        x = relative ? x + next() : next();
        y = relative ? y + next() : next();
        path.lineTo(x, y);
      case 'C':
      case 'c':
        final relative = command == 'c';
        final x1 = relative ? x + next() : next();
        final y1 = relative ? y + next() : next();
        final x2 = relative ? x + next() : next();
        final y2 = relative ? y + next() : next();
        final x3 = relative ? x + next() : next();
        final y3 = relative ? y + next() : next();
        path.cubicTo(x1, y1, x2, y2, x3, y3);
        x = x3;
        y = y3;
      default:
        index++;
    }
  }
  return path;
}

